    "exampleBn": "আর রাজা সলোমন যদি তার সমস্ত ধনরত্ন বেসমেন্টে স্তূপ করে রেখে সেই বাড়ির দারোয়ান হতেন, তবে জিম তার পাশ দিয়ে যাওয়ার সময় প্রতিবারই নিজের ঘড়িটা বের করে দেখাত—শুধু ঈর্ষায় সলোমনকে নিজের দাড়ি ছিঁড়তে দেখার জন্য।"
