    "partOfSpeech": "noun",
    "definition": "One of the five administrative divisions of New York City.",
    "exampleEn": "Although O. Henry does not mention New York by name at the start, he refers to Coney Island, the city's famous amusement park in the borough of Brooklyn, and mentions that Della had worshipped the combs for long in a Broadway window.",
    "exampleBn": "ও. হেনরি শুরুতে সরাসরি নিউ ইয়র্কের নাম উল্লেখ না করলেও ব্রুকলিনে অবস্থিত শহরের সবচেয়ে বিখ্যাত বিনোদন পার্ক ‘কোনি আইল্যান্ড’-এর কথা উল্লেখ করেছেন এবং বলেছেন যে ডেলা ব্রডওয়ের একটি দোকানের জানালায় দীর্ঘদিন ধরে চিরুনিগুলোর দিকে মুগ্ধ হয়ে তাকিয়ে থাকত।"
