    "exampleBn": "সমাজের বিশেষ কোনো দিককে আলাদা করে তুলে এনে ভাষার অবিশ্বাস্য পরিমিতি ও মাধুর্যের সাথে তা বর্ণনা করার ক্ষেত্রে তাঁর জুরি মেলা ভার।"
