    "exampleEn": "Meanwhile, Porter was accused of embezzling funds dating back to his employment at the First National Bank in Austin.",
    "exampleBn": "ইতিমধ্যে অস্টিনের ফার্স্ট ন্যাশনাল ব্যাংকে কর্মরত থাকাকালীন তহবিল তছরুপের অভিযোগে পোর্টার অভিযুক্ত হন।"
