    "exampleBn": "তাঁর অন্যান্য বিখ্যাত সংকলনের মধ্যে রয়েছে ‘ক্যাবেজেস অ্যান্ড কিংস’ (১৯০৪), ‘দ্য ফোর মিলিয়ন’ (১৯০৬, যাতে ‘দ্য গিফট অব দ্য মেজাই’ রয়েছে), ‘রোডস অব ডেস্টিনি’ এবং ‘সিক্সেস অ্যান্ড সেভেনস’।"
