    "exampleBn": "ও. হেনরি ফ্ল্যাটটির চিত্র ফুটিয়ে তোলার জন্য ঠিক যতটুকু প্রয়োজন ততটুকু বিবরণ দিয়েছেন: সস্তা, সামান্য আসবাবপত্রে সাজানো, ভাঙা চিঠির বাক্স এবং অকেজো কলিং বেল।"
