    "exampleEn": "Tumbling down on the couch with a smile, Jim suggests putting their Christmas presents away for a while because they are too nice to use just at present: he sold his gold watch to get the money to buy her combs, while she sacrificed her beautiful hair to buy the platinum fob chain for his watch.",
