    "exampleEn": "O. Henry's short stories are well known for their wit, wordplay, warm characterization, and clever twist endings.",
    "exampleBn": "ও. হেনরির ছোটগল্পগুলো সেগুলোর বুদ্ধিদীপ্ত রসবোধ, শব্দের চমৎকার খেলা, আন্তরিক চরিত্রায়ণ এবং চতুর চমকপ্রদ সমাপ্তির (twist endings) জন্য সুপরিচিত।"
