    "bengaliMeaning": "হালকা ও দ্রুত পায়ে ছুটে গেল (tripped by = দ্রুত পায়ে পেরিয়ে গেল)",
    "phonetic": "/trɪpt/",
    "partOfSpeech": "verb",
    "definition": "Moved quickly and lightly with nimble steps.",
