    "phonetic": "/ˈmeɪdʒaɪ/",
    "partOfSpeech": "plural noun",
    "definition": "The Three Wise Men from the East who followed a star to Bethlehem to bring gifts of gold, frankincense, and myrrh to the infant Jesus.",
