    "exampleBn": "কারণ সেখানেই রাখা ছিল সেই চিরুনি সেট — মাথার পাশে ও পেছনে পরার সেই চিরুনিগুলো, যেগুলো ব্রডওয়ের এক দোকানের কাঁচের জানালায় দেখে ডেলা দীর্ঘদিন ধরে মনে মনে আরাধনা করেছিল।"
